def colorpts(n,box,kind,minsize=3,maxsize=300):
 a=np.asarray(Image.open(f'images/fig_{n:02}.png').convert('RGB')).astype(int);x0,y0,x1,y1=box;a=a[y0:y1,x0:x1];r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
 if kind=='red':m=(r>g+25)&(r>b+20)&(r>90)
 elif kind=='blue':m=(b>r+20)&(b>g+5)&(b>60)
 elif kind=='orange':m=(r>160)&(g>75)&(b<130)&(r>g+20)
 l,num=label(m);out=[]
 for i,s in enumerate(find_objects(l),1):
  yy,xx=np.where(l[s]==i);sz=len(xx)
  if minsize<=sz<=maxsize:out.append((float(x0+s[1].start+xx.mean()),float(y0+s[0].start+yy.mean())))
 return out
